---IsUnlockFishPlace 渔场是否解锁
---@param fishingPlaceId integer @ 渔场id
---@return boolean
function FishingUtils.IsUnlockFishPlace(fishingPlaceId)
    fishingPlaceId = checkNumber(fishingPlaceId)
    if fishingPlaceId <= 0 then
        return false
    end
    local vo = FishingUtils.GetFishingPlaceVo(fishingPlaceId)
    if not vo then
        return false
    end
    return GameUtils.IsUnlocked(vo.unlockType, vo.unlockNum, vo.unlockId), GameUtils.GetUnlockDescr(vo.unlockType, vo.unlockNum, vo.unlockId)
    --local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
    --local level, exp = comp:GetCurLevelAndExp()
    --return level >= checkNumber(vo.level)
end

---IsCanFishHangUp 渔场是否可以挂机
---@param fishingPlaceId integer @ 渔场id
---@return boolean, string
function FishingUtils.IsCanFishHangUp(fishingPlaceId)
    if not FishingUtils.IsUnlockFishPlace(fishingPlaceId) then
        return false, FishingUtils.GetFishPlaceUnlockDesc(fishingPlaceId)        
    end
    local dojo = FishingUtils.GetFishingPlaceDojo(fishingPlaceId)
    if not dojo then
        return false, localize("该渔场全部收集完才可挂机")
    end
    if checkNumber(dojo.collectNum) < table.count(FishingUtils.GetAllFishVoByPlaceId(fishingPlaceId)) then
        return false, localize("该渔场全部收集完才可挂机")
    end
    return true
end

