---GetNextLevel 获取下一等级
---@param level number 
---@return integer
function FishingUtils.GetNextLevel(level)
    level = checkNumber(level)
    if level <= 0 then
        return 0
    end

    local t = CfUtils.GetCfTable(AutoIds.IdSetting1841)
    if not t then
        return nil
    end
    if level >= table.count(t) then
        return nil
    end
    return level + 1
end

