---GetAdditionDataByVo 从一个vo里拿到加成数据
---@param vo FishingLevelVo | FishingPullPowerVo | FishingCardBonusVo | FishingRodVo | FishingReelVo | FishingBaitVo | FishingLineVo
---@param type Constants.ChooseCardStatus
---@return table[] 
function FishingUtils.GetAdditionDataByVo(vo, type)
    if not vo then
        return {}
    end
    type = checkNumber(type)

    local types = {}
    local ids = {}
    local values = {}

    if type == Constants.ChooseCardStatus.FishHangeUp then
        types = CfUtils.Split(vo.additionType2)
        ids = CfUtils.Split(vo.additionCondition2)
        values = CfUtils.Split(vo.additionValue2)
    elseif type == Constants.ChooseCardStatus.FishAccompany then
        types = CfUtils.Split(vo.additionType1)
        ids = CfUtils.Split(vo.additionCondition1)
        values = CfUtils.Split(vo.additionValue1)
    else
        types = CfUtils.Split(vo.additionType)
        ids = CfUtils.Split(vo.additionCondition)
        values = CfUtils.Split(vo.additionValue)
    end

    if not types or not ids or not values then
        return {}
    end

    local t = {}
    local len = #types
    for i = 1, len do
        table.insert(t,{
            type = types[i],
            id = ids[i],
            value = values[i],
        })
    end
    return t
end

