---GetAdditonDesc 获取加成的描述
---@param addationData table
---@param isLevelShow boolean
---@return string
function FishingUtils.GetAdditionDesc(addationData, isLevelShow)
    if not addationData then
        return ""
    end
    local vo = FishingUtils.GetFishingBonusEffectVo(addationData.type)
    if not vo then
        return ""
    end

    local value = addationData.value
    local type = checkNumber(addationData.type)
    local globalTalentMgr = GlobalTalentMgr:GetInstance()
    if type == ConstantsFishing.AdditionType.FishProbabilityAdd then
        ---大鱼概率
        value = globalTalentMgr:CalcNum(value, Constants.GlobalTalentEffectId.Id_15, true, function(data)
            return true
        end)
    elseif type == ConstantsFishing.AdditionType.AddDamagePer then
        value = globalTalentMgr:CalcNum(value, Constants.GlobalTalentEffectId.Id_16, true, function(data)
            return true
        end)
    end
    local configValue = value
    if vo.isPercentage == 1 then
        value = checkInt(checkNumber(value) * 100).."%"
    end
    if isLevelShow then
        value = ""
    end
    local name = ""
    --渔场
    if type == ConstantsFishing.AdditionType.FishPoolBigFishProbabilityAdd or type == ConstantsFishing.AdditionType.FishPoolRareProbabilityAdd
      or type == ConstantsFishing.AdditionType.FishPoolProbabilityAdd or type == ConstantsFishing.AdditionType.FishPoolKagezoFishProbabilityAdd
      or type == ConstantsFishing.AdditionType.FishPoolDamageFirst then
        local vo = FishingUtils.GetFishingPlaceVo(addationData.id)
        if vo then
            name = vo.name
        end
    --鱼种
    elseif type == ConstantsFishing.AdditionType.FishGetProbabilityAdd then
        local vo = FishingUtils.GetFishingSpeciesVo(addationData.id)
        if vo then
            name = vo.name
        end
    elseif type == ConstantsFishing.AdditionType.PropsProbabilityAdd then
        if checkNumber(addationData.id) == ConstantsFishing.PropsType.Fish then
            name = localize("渔具")
        elseif checkNumber(addationData.id) == ConstantsFishing.PropsType.Material then
            name = localize("材料")
        end
    elseif type == ConstantsFishing.AdditionType.AddFishSpeed then
        if checkNumber(addationData.id) == ConstantsFishing.FishStatus.Common then
            name = localize("基础速度")
        elseif checkNumber(addationData.id) == ConstantsFishing.FishStatus.RunAway then
            name = localize("逃逸速度")
        end
    else
        name = addationData.id
    end
    return string.fmt(vo.name, {_Condition = name, _Value = value}), configValue
end

---GetAdditionNoValueDesc 获取加成的描述 没有value值
---@param addationData table
---@param isLevelShow boolean
---@param isName2 boolean
---@return string
function FishingUtils.GetAdditionNoValueDesc(addationData, isLevelShow, isName2)
    if not addationData then
        return ""
    end
    local vo = FishingUtils.GetFishingBonusEffectVo(addationData.type)
    if not vo then
        return ""
    end

    local value = addationData.value
    if vo.isPercentage == 1 then
        value = ""
    end
    if isLevelShow then
        value = ""
    end
    local name = ""
    local type = checkNumber(addationData.type)
    --渔场
    if type == ConstantsFishing.AdditionType.FishPoolBigFishProbabilityAdd or type == ConstantsFishing.AdditionType.FishPoolRareProbabilityAdd
      or type == ConstantsFishing.AdditionType.FishPoolProbabilityAdd or type == ConstantsFishing.AdditionType.FishPoolKagezoFishProbabilityAdd
      or type == ConstantsFishing.AdditionType.FishPoolDamageFirst then
        local placeVo = FishingUtils.GetFishingPlaceVo(addationData.id)
        if placeVo then
            name = placeVo.name
        end
    --鱼种
    elseif type == ConstantsFishing.AdditionType.FishGetProbabilityAdd then
        local vo2 = FishingUtils.GetFishingSpeciesVo(addationData.id)
        if vo2 then
            name = vo2.name
        end
    elseif type == ConstantsFishing.AdditionType.PropsProbabilityAdd then
        if checkNumber(addationData.id) == ConstantsFishing.PropsType.Fish then
            name = localize("渔具")
        elseif checkNumber(addationData.id) == ConstantsFishing.PropsType.Material then
            name = localize("材料")
        end
    elseif type == ConstantsFishing.AdditionType.AddFishSpeed then
        if checkNumber(addationData.id) == ConstantsFishing.FishStatus.Common then
            name = localize("基础速度")
        elseif checkNumber(addationData.id) == ConstantsFishing.FishStatus.RunAway then
            name = localize("逃逸速度")
        end
    else
        name = addationData.id
    end
    if isName2 then
        return string.fmt(vo.name2, {_Condition = name, _Value = value})
    else
        return string.fmt(vo.name, {_Condition = name, _Value = value})
    end
end

---GetHangUpCardNumByLevel 获取该等级解锁的挂机人数
---@param level integer
---@return integer
function FishingUtils.GetHangUpCardNumByLevel(level)
    level = checkNumber(level)
    if level <= 0 then
        return 0
    end
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
    local t = comp:GetHangUpLevelContrast()

    if not t then
        return 0
    end
    local num = 0
    for k ,v in pairs(t) do
        if checkNumber(k) <= level then
            num = num + 1
        end
    end
    return num
end

---GetFishingGoodsDojo 获取钓鱼道具数据
---@param goodsId integer @ 道具id 
---@return FishingGoodsDojo
function FishingUtils.GetFishingGoodsDojo(goodsId)
