---@param goodsId integer @ 道具id 
---@return string | number | nil
function FishingUtils.GetFishingGoodsShowNumText(goodsId)
    goodsId = checkNumber(goodsId)
    if goodsId <= 0 then
        return nil
    end
    --if FishingUtils.IsBaseProps(goodsId) then
    --    return nil
    --end

    local type = GoodsUtils.GetIdType(goodsId)
    local dojo = FishingUtils.GetFishingGoodsDojo(goodsId)
    --显示耐久度
    if type == Constants.IDType.GoodsReel or type == Constants.IDType.GoodsFishingRod then
        local vo = FishingUtils.GetFishingGoodsVoById(goodsId)
        if vo then
            if checkNumber(vo.durability) == -1 then
                return nil
            end
            ---已拥有
            if dojo then
                return dojo.durability.."/"..vo.durability
            else
                return vo.durability.."/"..vo.durability
            end
        end
    elseif type == Constants.IDType.GoodsBait or type == Constants.IDType.GoodsFishingLine then
        ---已拥有
        if dojo then
            return "x"..checkNumber(dojo.num)
        else
            return nil
        end
    end
    return nil
end

