---GetDamageFactorByVo 获取伤害系数 默认返回1
---@param vo FishingPullPowerVo @ 包含加成类型的一个vo
---@return integer
function FishingUtils.GetDamageFactorByVo(vo)
    if not vo then
        return 0
    end

    local t = FishingUtils.GetAdditionDataByVo(vo)
    if not t then
        return 0
    end

    local num = 0
    for k, v in pairs(t) do
        if checkNumber(v.type) == ConstantsFishing.AdditionType.AddDamage then
            num = num + checkNumber(v.value)
        end
    end

    return num
end

