    force = checkNumber(force)
    local t = FishingUtils.GetAllFishingPullPowerVo()
    if not t then
        return nil
    end
    local num = 0
    for k, v in pairs(t) do
        num = num + checkNumber(v.weight)
        if force <= num then
            return v
        end
    end
    return nil
end

