function FishingUtils.GetFishingAdditionValueByVo(vo, type, id)
    if not vo then
        return 0
    end
    local num = 0
    local data = FishingUtils.GetAdditionDataByVo(vo)
    if data then
        for k, v in pairs(data) do
            if checkNumber(v.type) == checkNumber(type) and checkNumber(id) == checkNumber(v.id) then
                num = num + checkNumber(v.value)
            end 
        end
    end
    return num
end

