---GetFishCardBuffData 获取钓鱼卡牌buff
---@param cardId integer @ 卡牌id
---@param type integer
---@return table[]
function FishingUtils.GetFishCardBuffData(cardId, type)
    type = checkNumber(type)
    local vo = FishingUtils.GetFishingCardBonusVo(cardId)
    if not vo then
        return {}
    end
    local t = {}
    local buffData = FishingUtils.GetAdditionDataByVo(vo, type)

    local stars = {}
    if type == Constants.ChooseCardStatus.FishHangeUp then
        stars = CfUtils.Split(vo.starLv2)
    elseif type == Constants.ChooseCardStatus.FishAccompany then
        stars = CfUtils.Split(vo.starLv1)
    end
    if stars then
        for k, v in pairs(stars) do
            table.insert(t, {
                starKey = v,
                buffData = buffData[k],
            })
        end
    end
    return t
end

---GetActiveCardBuffData 获取卡牌激活的挂机buff
---@param id integer @ 卡牌唯一id
---@param type integer
---@return table[]
function FishingUtils.GetActiveCardBuffData(id, type)
    if checkNumber(id) <= 0 then
        return {}
    end
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComp:GetCardById(checkString(id))
    if not cardDojo then
        return {} 
    end

    local vo = FishingUtils.GetFishingCardBonusVo(cardDojo.cardId)
    if not vo then
        return {}
    end

    local t = {}
    local buffData = FishingUtils.GetAdditionDataByVo(vo, type)
    local stars 
    if type == Constants.ChooseCardStatus.FishAccompany then
        stars = CfUtils.Split(vo.starLv1)
    else
        stars = CfUtils.Split(vo.starLv2)
    end
    if stars then
        for k, v in pairs(stars) do
            if checkNumber(cardDojo.star) >= checkNumber(v) then
                table.insert(t, {
                    starKey = v,
                    buffData = buffData[k],
                })
            end
        end
    end
    return t
end

