---IsUnlockQueueById 是否解锁了队列 
---@param queueId integer @ 队列id
---@return boolean
function FishingUtils.IsUnlockQueueById(queueId)
    local maxNum = FishingUtils.GetFishTeamMaxNum(queueId)
    if maxNum < 1 then
        return false
    end

    for i = 1, maxNum do
        if FishingUtils.IsUnlockTeamPosByQueueAndCol(queueId, i) then
            return true
        end
    end
    return false
end

---GetCardFishHangUpData 获取挂机卡牌数据
---@param id integer @ 卡牌唯一id
---@return FishingFishHangUpQueueDojo
function FishingUtils.GetCardFishHangUpData(id)
    if checkNumber(id) == 0 then
        return nil
    end

    ---@type FishingComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
    local t = comp:GetFishTeamInfo()
    if not t then
        return nil
    end
    for k, v in pairs(t) do
        local cardStr = v.cards
        if cardStr then
            local cards = CfUtils.Split(cardStr, ",")
            for _, refId in pairs(cards) do
                if checkNumber(refId) == checkNumber(id) then
                    return v
                end
            end
        end
    end
    return nil
end

