---GetFishTeamByHangUpQueueId 获取队伍信息 
---@param queueId integer @ 队列id
---@return TeamMemberDojo[]
function FishingUtils.GetFishTeamByHangUpQueueId(queueId)
    local dojo = FishingUtils.GetHangUpDojoByQueueId(queueId)
    if not dojo then
        return nil
    end
    local maxNum = FishingUtils.GetFishTeamMaxNum(queueId)
    if maxNum <= 0 then
        return nil
    end

    local t = {}
    local cards = {}
    if dojo.cards then
        cards = CfUtils.Split(dojo.cards, ",")
    end
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    for i = 1, maxNum do
        local cardId = 0
        if checkNumber(cards[i]) > 0 then
            local cardDojo = cardComp:GetCardById(checkString(cards[i]))
            if cardDojo then
                cardId = cardDojo.cardId
            end
        end
        local data = CfUtils.GetTeamMemberData(Constants.TeamMemberType.PlayerCard, checkNumber(cards[i]), cardId)
        table.insert(t, data)
    end
    return t
end

