---IsUnlockTeamPosByQueueAndCol 是否解锁了挂机位置
---@param queueId integer @ 队列id
---@param col integer @ 位置
---@return boolean, string
function FishingUtils.IsUnlockTeamPosByQueueAndCol(queueId, col)
    local vo = FishingUtils.GetFishingHangUpUnlockVoByQueueAndCol(queueId, col)
    if not vo then
        return false, ""
    end

    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
    local level, exp = comp:GetCurLevelAndExp()
    local err = localize("钓鱼等级_num_解锁", {_num_ = vo.level})
    return level >= checkNumber(vo.level), err
end

---GetFishTeamFreePos 获取该队伍中第一个可以上阵的位置
---@param queueId integer @ 队列id
---@param bufferTeam table
---@return integer
function FishingUtils.GetFishTeamFreePos(queueId, bufferTeam)
    queueId = checkNumber(queueId)
    if queueId <= 0 then
        return 0
    end
    if not bufferTeam then
        return 0
    end
    local maxNum = FishingUtils.GetFishTeamMaxNum(queueId)
    if maxNum <= 0 then
        return 0
    end
    for i = 1, maxNum do
        local isUnlock = FishingUtils.IsUnlockTeamPosByQueueAndCol(queueId, i)
        --解锁了这个位置
        if isUnlock then
            if not bufferTeam[i] or checkNumber(bufferTeam[i].refId) == 0 then
                return i
            end
        end
    end 
    return 0
end

---GetHangUpConsumes 获取钓场消耗的东西
---@param placeId integer @ 钓场id
---@return table[]
function FishingUtils.GetHangUpConsumes(placeId)
    local vo = FishingUtils.GetFishingPlaceVo(placeId)
    if not vo then
        return {}
    end
    local t = {}
    local ids = CfUtils.Split(vo.currency)
    local nums = CfUtils.Split(vo.num)
    for k, v in pairs(ids) do
        table.insert(t, {
           goodsId = checkNumber(ids[k]),
           num = checkNumber(nums[k])
       }) 
    end
    return t
end

--- 获取buff数据  value的总量
---@param buffData table
---@return table[]
function FishingUtils.GetBuffTotalValueData(buffData)
    buffData = checkTable(buffData)
    local t = {}
    for k, v in pairs(buffData) do
        if t[checkString(v.buffData.type)] then
            t[checkString(v.buffData.type)].value = t[checkString(v.buffData.type)].value + checkNumber(v.buffData.value)
        else
            t[checkString(v.buffData.type)] = {
                value = checkNumber(v.buffData.value),
                buffData = v.buffData
            } 
        end
    end

    local _t = {}
    for k, v in pairs(t) do
        table.insert(_t, {
            value = v.value,
            buffData = v.buffData
        })
    end
    return _t
end

--- 队列挂机实际消耗的金币数量
---@param queueId integer
---@return number
function FishingUtils.GetQueueGoldConsume(queueId)
    queueId = checkNumber(queueId)
    if queueId <= 0 then
        return 0
    end
    local dojo = FishingUtils.GetHangUpDojoByQueueId(queueId)
    if not dojo then
        return 0
    end
    if string.isEmpty(checkString(dojo.cards)) then
        return 0
    end

    local t1 = {}
    local t = CfUtils.Split(dojo.cards, ",")
    for k, id in pairs(t) do
        local buffData = FishingUtils.GetActiveCardBuffData(id, Constants.ChooseCardStatus.FishHangeUp) 
        for _, v in pairs(buffData) do
            table.insert(t1, v)
        end
    end

    local t2 = FishingUtils.GetBuffTotalValueData(t1)
    for k, v in pairs(t2) do
        --金币打折
        if checkNumber(v.buffData.type) == ConstantsFishing.AdditionType.GoldDel then
            return v.value
        end
    end
    return 0
end


