---GetCurHangUpNum 获取当前挂机次数
---@param queueId integer @ 队列id
---@return integer
function FishingUtils.GetCurHangUpNum(queueId)
    local isHaveTask = FishingUtils.IsHangeUpQueueHasTask(queueId)
    --没任务直接返回
    if not isHaveTask then
        return 0
    end

    local dojo = FishingUtils.GetHangUpDojoByQueueId(queueId)
    if not dojo then
        return 0
    end

    local oneTime = FishingUtils.GetFishHangUpTime()
    return math.ceil(checkNumber(dojo.remainTime) / oneTime)
end

---GetCurHangUpFinishNum 获取当前挂机完成次数
---@param queueId integer @ 队列id
---@return integer
function FishingUtils.GetCurHangUpFinishNum(queueId)
    local isHaveTask = FishingUtils.IsHangeUpQueueHasTask(queueId)
    --没任务直接返回
    if not isHaveTask then
        return 0
    end

    local dojo = FishingUtils.GetHangUpDojoByQueueId(queueId)
    if not dojo then
        return 0
    end

    local oneTime = FishingUtils.GetFishHangUpTime()
    return math.floor((checkNumber(dojo.totalTimes) * oneTime - checkNumber(dojo.remainTime)) / oneTime)
end

---GetMaxHangUpNum 获取该队列最大挂机次数
---@param queueId integer @ 队列id
---@return integer
function FishingUtils.GetMaxHangUpNum(queueId)
    local dojo = FishingUtils.GetHangUpDojoByQueueId(queueId)
    if not dojo then
        return 0
    end
    local cards = {}
    if dojo.cards then
        cards = CfUtils.Split(dojo.cards, ",")
    end
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
    local energyNum = 0
    local cardsNum = 0   --编队卡牌数量
    for k, v in pairs(cards) do
        if checkNumber(v) > 0 then
            cardsNum = cardsNum + 1
            local _num = FishingUtils.GetFishCardEnergyNum(v)
            if energyNum == 0 then
                energyNum = _num
            elseif energyNum > _num then
                energyNum = _num
            end
        end
    end

    return math.floor(energyNum / FishingUtils.GetFishHangUpEnergyNum()) * cardsNum
end

