---IsUnlockLimitDatas 是否满足限制条件
---@param limitData table @ 限制信息
---@param paraData table @ 参数信息  {fishPlaceId}
---@return boolean, string
function FishingUtils.IsUnlockLimitDatas(limitData, paraData)
    if not limitData then
        return true, ""
    end
    for k, v in pairs(limitData) do
        local isUnlock, err = FishingUtils.IsUnlockLimitData(v, paraData)
        if not isUnlock then
            return false, err
        end
    end
    return true, ""
end

---IsUnlockLimitData 是否满足限制条件
---@param limitData table @ 限制信息
---@param paraData table @ 参数信息
---@return boolean, string
function FishingUtils.IsUnlockLimitData(limitData, paraData)
    if not limitData then
        return true
    end
    local err = ""
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)

    local limitId = checkNumber(limitData.limitId)
    local limitValue = limitData.limitValue
    if limitId == ConstantsFishing.LimitType.GoodsId then
        local type = GoodsUtils.GetIdType(limitValue)
        local targetId = 0
        if type == Constants.IDType.GoodsReel then
            targetId = comp:GetCurEquipReelId(paraData.fishPlaceId)
        elseif type == Constants.IDType.GoodsFishingRod then
            targetId = comp:GetCurEquipRodId(paraData.fishPlaceId)
        elseif type == Constants.IDType.GoodsBait then
            targetId = comp:GetCurEquipBaitId(paraData.fishPlaceId)
        elseif type == Constants.IDType.GoodsFishingLine then
            targetId = comp:GetCurEquipWireId(paraData.fishPlaceId)
        end
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(limitValue)
        if checkNumber(targetId) ~= checkNumber(limitValue) then
            if vo then
                err = localize("仅限使用_name_", {_name_ = vo.name}) 
            end
            return false, err
        end
    elseif limitId == ConstantsFishing.LimitType.AccompanyCardId then
        paraData = checkTable(paraData)
        local fishPlaceDojo = comp:GetFishingPlaceDojo(paraData.fishPlaceId)
        if fishPlaceDojo then
            local id = checkNumber(fishPlaceDojo.partner)
            if id > 0 then
                local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                local cardDojo = cardComp:GetCardById(checkString(id))
                if cardDojo then 
                    if checkNumber(cardDojo.cardId) == checkNumber(limitValue) then
                        return true
                    end
                end
            end
        end
        local vo = CardConfMgr:GetInstance():GetCardByRefId(limitValue)
        if vo then
            err = localize("仅限_name_武装陪钓", {_name_ = vo.name}) 
        end
        return false, err
    elseif limitId == ConstantsFishing.LimitType.AccompanyCardStar then
        paraData = checkTable(paraData)
        local fishPlaceDojo = comp:GetFishingPlaceDojo(paraData.fishPlaceId)
        if fishPlaceDojo then
            local id = checkNumber(fishPlaceDojo.partner)
            if id > 0 then
                local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                local cardDojo = cardComp:GetCardById(checkString(id))
                if cardDojo then 
                    if checkNumber(cardDojo.star) >= checkNumber(limitValue) then
                        return true
                    end
                end
            end
        end
        err = localize("仅限_name_星及以上武装陪钓", {_name_ = limitValue})
        return false, err
    elseif limitId == ConstantsFishing.LimitType.FishPlace then
        paraData = checkTable(paraData)
        if checkNumber(paraData.fishPlaceId) ~= checkNumber(limitValue) then
            local vo = FishingUtils.GetFishingPlaceVo(limitValue)
            if vo then
                err = localize("仅限_name_渔场使用", {_name_ = vo.name})
            end
            return false, err
        end
    end
    return true
end

