        local FishingSpeciesVo = import("Game.Setting.Vo.FishingSpeciesVo")
        local t = CfUtils.GetCfTable(AutoIds.IdSetting1854)
        if t then
            for k, v in pairs(t) do
                local vo = FishingSpeciesVo.New()
                vo:FillVo(v)
                if checkNumber(vo.id) ~= 800110 then 
                    if not allFishVo[checkNumber(vo.pond)] then
