---GetTalkStrById 获取钓鱼时说的话
---@param talkId integer
---@param para integer
---@return string
function FishingUtils.GetTalkStrById(talkId, para)
    local vo = FishingUtils.GetFishingTalkVo(talkId)
    if not vo then
        return ""
    end
    local str = vo.content
    local cdtType = checkNumber(vo.condition)

    if cdtType == ConstantsFishing.TalkType.FishFailBreakLine or cdtType == ConstantsFishing.TalkType.FishFailBreakFree or 
      cdtType == ConstantsFishing.TalkType.FishFailDisOut then
        local fishVo = GoodsConfMgr:GetInstance():GetGoodsVoById(para)
        if fishVo then
            local colStr =  FishingUtils.GetColorByQuality(fishVo.quality)
            colStr = string.fmt(colStr, {_name_ = fishVo.name})
            str = string.fmt(str, {_fishName_ = colStr})
        end
    end
    return str
end

