---GetHangUpConsumeEnergyData 获取挂机精力消耗后的值
---@param queueId integer @ 队列id 
---@param num integer
function FishingUtils.GetHangUpConsumeEnergyData(queueId, num)
    num = checkNumber(num)
    queueId = checkNumber(queueId)
    if checkNumber(queueId) <= 0 then
        return {}
    end

    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
    local dojo = comp:GetHangUpDojoByQueueId(queueId)
    if not dojo then
        return {}
    end
    local cardsData = CfUtils.Split(checkString(dojo.cards), ",")
    local t = {}
    --编队成员
    local cardsNum = 0
    for k, v in pairs(cardsData) do
        if checkNumber(v) > 0 then
            cardsNum = cardsNum + 1
            table.insert(t, {
                cardId = v,
                num = FishingUtils.GetFishCardEnergyNum(v)
            })
        end
    end
    if cardsNum <= 0 then
        return {}
    end

    for i = 1, num do
        local key = i%cardsNum
        if key == 0 then
            key = cardsNum
        end
        t[key].num = t[key].num - FishingUtils.GetFishHangUpEnergyNum()
    end

    return t
end 

