function FishingUtils.IsHaveCanDrawAtlasReward(placeId)
    local t = FishingUtils.GetAllAtlasRewardId(placeId)
    for k, v in pairs(t) do
        local data = FishingUtils.GetFishingAtlasRewardVo(v)
        local isDraw = FishingUtils.IsDrawAtlasReward(data.id)
        local isUnlock = FishingUtils.IsUnlockAtlasId(data.id)
        local isCanDraw = (isUnlock and not isDraw)
        if isCanDraw then
            return true
        end
    end
    return false
end

function FishingUtils.GetFishEnoughNum(boxId)
    local num = 0
    local vo = FishingUtils.GetFishingAtlasRewardVo(boxId)
    if not vo then 
        return num
    end

    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
    local t = FishingUtils.GetAllFishVoByPlaceId(vo.pond)
    for k, v in pairs(t) do
        print(v)
        local dojo = comp:GetFishCollectionDojoByFishId(v.id)
        if dojo then
            if checkNumber(dojo.rating) >= checkNumber(vo.grade) then
                num = num + 1
            end
        end
    end

    return num
end

function FishingUtils.IsUnlockAtlasId(boxId)
    local vo = FishingUtils.GetFishingAtlasRewardVo(boxId)
    if not vo then 
        return false
    end
    
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
    local t = FishingUtils.GetAllFishVoByPlaceId(vo.pond)
    for k, v in pairs(t) do
        local dojo = comp:GetFishCollectionDojoByFishId(v.id)
        if dojo then
            if checkNumber(dojo.rating) < checkNumber(vo.grade) then
                return false
            end
        else
            return false
        end
    end

    return true
end

function FishingUtils.GetAtlasGetNum(placeId)
    local t = FishingUtils.GetAllFishVoByPlaceId(placeId)
    local num = 0
    for k, v in pairs(t) do
        local isCollect = FishingUtils.IsCollectionGetFishById(v.id)
        if isCollect then
            num = num + 1
        end
    end
    return num, #t
end 

--- 获取已经获得的彩蛋数量
---@param groupId integer
---@return integer, integer
function FishingUtils.GetEasterEggsGetNum(groupId)
    local vo = FishingUtils.GetFishEasterEggsGroupVo(groupId)
    local t = CfUtils.Split(vo.item)
    local num = 0
    for k, v in pairs(t) do
