--- 获取彩蛋分组的vo 根据彩蛋id
---@param easterEggsId integer
---@return FishEasterEggsGroupVo
function FishingUtils.GetEasterEggsGroupVoByEggId(easterEggsId)
    local FishEasterEggsGroupVo = import("Game.Setting.Vo.FishEasterEggsGroupVo")
    local t = CfUtils.GetCfTable(AutoIds.IdSetting2026)
    if t then
        for k, v in pairs(t) do
            local vo = FishEasterEggsGroupVo.New()
            vo:FillVo(v)

            local _t = CfUtils.Split(vo.item)
            for _k, _v in pairs(_t) do
                if checkNumber(_v) == checkNumber(easterEggsId) then 
                    return vo
                end
            end
        end     
    end
    return nil
end

--- 是否可以领取奖励
