---@return boolean
function FishingUtils.IsCanDrawReard(groupId)
    local curNum, allNum = FishingUtils.GetEasterEggsGetNum(groupId)
    local isGet = FishingUtils.IsDrawEasterEggsReward(groupId)
    if curNum >= allNum then
