--是否领取了积分奖励
function FishingUtils.IsDrawIntegralReward(fishPlaceId, rewardId)
    if checkNumber(fishPlaceId) <= 0 or checkNumber(rewardId) <= 0 then
        return false
    end

    local data = FishingUtils.GetFishPlaceDojoActivityData(fishPlaceId)
    if not data then
        return false
    end

    local t = checkTable(data.receivedScoreRewards)
    if not t or table.count(t) <= 0 then
        return false
    end

    for k, v in pairs(t) do
        if checkNumber(rewardId) == checkNumber(v) then
            return true
        end
    end

    return false
end

--是否可以领取积分奖励
function FishingUtils.IsCanDrawIntegralReward(fishPlaceId, rewardId)
    ----已领取
    --if FishingUtils.IsDrawIntegralReward(fishPlaceId, rewardId) then
    --    return false
    --end

    local data = FishingUtils.GetFishPlaceDojoActivityData(fishPlaceId)
    if not data then
        return false
    end

    local vo = FishingUtils.GetFishIntegralRewardVo(rewardId)
    if not vo then
        return false
    end

    return checkNumber(data.score) >= checkNumber(vo.point) 
end

function FishingUtils.IsShowPlaceRedPoint(placeId)
    if checkNumber(placeId) <= 0 then
        return false
    end

    local isUnlock = FishingUtils.IsUnlockFishPlace(placeId)
    local redPointCom = GameUtils.GetEntityCompByType(ECSComponentType.Constants.RedPointMgrComponent)

    if isUnlock then
        if FishingUtils.IsHaveCanDrawIntegralReward(placeId) then
            return true
        end

        local data = FishingUtils.GetFishPlaceDojoActivityData(placeId)
        if data then
            local vo = FishingUtils.GetFishActivityPlanVo(data.contentId)
            --有活动
            if vo then
                if checkNumber(vo.activity) == ConstantsFishing.ActivityType.Summer then
                     --没领礼包
                    if checkNumber(data.receivedTicket) == 0 then
                        return true
                    end
                elseif checkNumber(vo.activity) == ConstantsFishing.ActivityType.KingChallenge then
                    local num1 = checkNumber(redPointCom:GetNodeNum(Constants.RedPointConst.PhoneFishActivityExchange))
                    local num2 = checkNumber(redPointCom:GetNodeNum(Constants.RedPointConst.PhoneFishActivityTask))

                    if num1 > 0 or num2 > 0 then
                        return true
                    end
                end
            end
        end
    end

    return false
end

