--主界面入口小红点是否可以亮
function FishingUtils.IsShowFishRedPoint()
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id233)
    if not isUnlock then
        return false
    end

    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)

    local t = comp:GetFishingPlaces()
    if not t then
        return false
    end
    local redPointCom = GameUtils.GetEntityCompByType(ECSComponentType.Constants.RedPointMgrComponent)

    for k, v in pairs(t) do
        local isUnlock = FishingUtils.IsUnlockFishPlace(k)

        if isUnlock then
            if FishingUtils.IsHaveCanDrawIntegralReward(k) then
                return true
            end
    
            local data = FishingUtils.GetFishPlaceDojoActivityData(k, ConstantsFishing.ActivityType.Summer)
            if data then
                local vo = FishingUtils.GetFishActivityPlanVo(data.contentId)
                --有活动
                if vo then
                    if checkNumber(vo.activity) == ConstantsFishing.ActivityType.Summer then
                         --没领礼包
                        if checkNumber(data.receivedTicket) == 0 then
                            return true
                        end
                    elseif checkNumber(vo.activity) == ConstantsFishing.ActivityType.KingChallenge then
                        local num1 = checkNumber(redPointCom:GetNodeNum(Constants.RedPointConst.PhoneFishActivityExchange))
                        local num2 = checkNumber(redPointCom:GetNodeNum(Constants.RedPointConst.PhoneFishActivityTask))

                        if num1 > 0 or num2 > 0 then
                            return true
                        end
                    end
                end
            end
        end
    end

    return false
end

--是否有积分奖励可领取
function FishingUtils.IsHaveCanDrawIntegralReward(fishPlaceId)
    local id = FishingUtils.GetFishPlaceActivityId(fishPlaceId)
    if checkNumber(id) <= 0 then
        return false
    end

    if checkNumber(id) ~= ConstantsFishing.ActivityType.Summer then
        return false
    end

    local t = FishingUtils.GetAllIntegralReward(id)
    if not t then
        return false
    end
    for k, v in pairs(t) do
        if FishingUtils.IsCanDrawIntegralReward(fishPlaceId, v) and (not FishingUtils.IsDrawIntegralReward(fishPlaceId, v)) then
            return true
        end
    end

    return false
end

--获取所有可领取的奖励
function FishingUtils.GetAllCanDrawIntegralRewardId(fishPlaceId)
    local _t = {}
    local id = FishingUtils.GetFishPlaceActivityId(fishPlaceId)
    if checkNumber(id) <= 0 then
        return _t
    end

    local t = FishingUtils.GetAllIntegralReward(id)
    if not t then
        return _t
    end
    for k, v in pairs(t) do
        if FishingUtils.IsCanDrawIntegralReward(fishPlaceId, v) and (not FishingUtils.IsDrawIntegralReward(fishPlaceId, v)) then
            table.insert(_t, v)
        end
    end

    return _t
end

--剩余兑换次数
function FishingUtils.GetRemainExchangeNum(fishPlaceId, exchangeId)
    local data = FishingUtils.GetFishPlaceDojoActivityData(fishPlaceId)
    if not data then
        return 0
    end

    local vo = FishingUtils.GetFishExchangeVo(exchangeId)
    if not vo then
        return 0
    end

    local maxNum = checkNumber(vo.stock)
    local curUseNum = 0

    local t = checkTable(data.remainExchangeTimes)
    for k, v in pairs(t) do
        if checkNumber(k) == checkNumber(exchangeId) then
            curUseNum = checkNumber(v)
        end
    end

    return curUseNum
    --return checkNumber(data.remainExchangeTimes)
end

function FishingUtils.GetRankRewardByRankNum(rankNum, activityId)
    rankNum = checkNumber(rankNum)

    local vos = CfUtils.GetCf(AutoIds.IdSetting2711, "FishRankingRewardVo", true)

    for k, v in pairs(vos) do
        if checkNumber(v.upperLimit) <= rankNum and checkNumber(v.lowerLimit) >= rankNum and checkNumber(activityId) == checkNumber(v.activityId) then
            local t = {}
            local rewardT = CfUtils.Split(v.reward)
            local rewardNumT = CfUtils.Split(v.rewardNum)
            for k, v in pairs(rewardT) do
                table.insert(t, {
                    goodsId = rewardT[k],
                    num = rewardNumT[k],
                })
            end
            return t
        end
    end
    return {}
end

