--所有的而外奖励
function FishingUtils.GetFishingAllTaskExtraRewards(id)
    local vo = FishingUtils.GetFishingTaskVo(id)
    if not vo then
        return {}
    end

    local t1 = checkTable(CfUtils.Split(vo.exceedTask))
    local t2 = CfUtils.Split(vo.exceedReward)
    local t3 = CfUtils.Split(vo.exceedNum)

    local _t = {}
    for i = 1, #t1 do
        local t4 = CfUtils.Split(t2[i], ",")
        local t5 = CfUtils.Split(t3[i], ",")

        local t = {}
        for i = 1, #t4 do
            table.insert(t, {
                goodsId = t4[i],
                num = t5[i],
            })
        end
        table.insert(_t, {
            rate = checkNumber(t1[i]),
            data = t,
        })
    end
    return _t
end

--任务额外达成的奖励
function FishingUtils.GetFishingTaskExtraRewards(id, targetNum)
    local vo = FishingUtils.GetFishingTaskVo(id)
    if not vo then
        return {}
    end

    local t1 = checkTable(CfUtils.Split(vo.exceedTask))
    local t2 = CfUtils.Split(vo.exceedReward)
    local t3 = CfUtils.Split(vo.exceedNum)

    local ind = 0
    for k, v in pairs(t1) do
        if checkNumber(v) == checkNumber(targetNum) then
            ind = k
        end
    end
    if checkNumber(ind) <= 0 then
        return {}
    end

    local t4 = CfUtils.Split(t2[ind], ",")
    local t5 = CfUtils.Split(t3[ind], ",")

    local _t = {}
    for i = 1, #t4 do
        table.insert(_t, {
            goodsId = t4[i],
            num = t5[i],
        })
    end
    return _t
end

--获取已经达成的奖励
function FishingUtils.GetFishingTaskReachExtraRewards(id, targetNum)
    local vo = FishingUtils.GetFishingTaskVo(id)
    if not vo then
        return {}
    end
    local t1 = checkTable(CfUtils.Split(vo.exceedTask))
    
    local _t = {}
    for k, v in pairs(t1) do
        if checkNumber(v) > 0 then
            if checkNumber(targetNum) >= checkNumber(v) then
                local t = FishingUtils.GetFishingTaskExtraRewards(id, v)
                for k, v in pairs(t) do
                    table.insert(_t, {
                        goodsId = v.goodsId,
                        num = v.num,
                    })
                end
            end
        end
    end

    return _t
end

