--是否解锁自动
function FishingUtils.IsUnlockAuto(placeId)
    local dojo = FishingUtils.GetFishingPlaceDojo(placeId)
    if not dojo then
        return false
    end

    local curNum, allNum = FishingUtils.GetAtlasGetNum(placeId)
    
    --数据不一样  俩者or
    return (curNum >= allNum) or (checkNumber(dojo.collectNum) >= table.count(FishingUtils.GetAllFishVoByPlaceId(placeId)))
    --[[
    local StoreUtils = import('Game.UI.Store.StoreUtils')
    local setting = SettingMgr:GetInstance():GetSetting(AutoIds.IdSetting602, "MonthCardRewardVo")
    local monthVo = checkTable(setting:GetAll()[1])
    local monthCardId = checkInt(monthVo.refId)
    
    return StoreUtils.GetStoreComp():IsMonthCardActive(monthCardId)
    ]]
end

--是否自动中
function FishingUtils.IsAutoing()
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
    return comp:IsAutoing()
end

--剩余自动次数
function FishingUtils.GetRemainAutoNum()
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
    return comp:GetAutoNum() - comp:GetAutoFinishNum()
end

function FishingUtils.GetAutoTargetForceId()
    return 4
end

function FishingUtils.GetAutoPageWaitTime()
    return 1
end

function FishingUtils.GetMaxAutoNum()
    local vo = FishingUtils.GetFishingParaVo(29)
    if not vo then
        return 0
    end
    return checkNumber(vo.parameter1)
end

function FishingUtils.IsAutoFix()
    local num = checkNumber(CS.Engine.Lib.KCookie.Get("FishAutoFix"))
    return (num == 1)
end

function FishingUtils.IsGoodsNew(id)
    local strs = CfUtils.GetLocalData("FishNewGoods")
    local t = checkTable(CfUtils.Split(strs))
    for k, v in pairs(t) do
        if checkNumber(id) == checkNumber(v) then
            return true
        end
    end
    return false 
end

function FishingUtils.DelGoodsNew(id)
    local strs = CfUtils.GetLocalData("FishNewGoods")
    local t = checkTable(CfUtils.Split(strs))
    for i = table.count(t), 1, -1 do
        if checkNumber(id) == checkNumber(t[i]) then
            table.remove(t, i)
        end
    end

    local strs = ""
    for k, v in pairs(t) do
        if k  > 1 then
            strs = strs..";"..v
        else
            strs = v
        end
    end
    CfUtils.WriteLocalData("FishNewGoods", strs)
end

function FishingUtils.HandleMainQuestPass(questId)
    local _t = {}
    local t = CfUtils.GetCf(AutoIds.IdSetting1840, "FishingPlaceVo", true)
    for k, v in pairs(t) do
        if checkNumber(v.unlockNum) == checkNumber(questId) then
            local t1 = CfUtils.GetCf(AutoIds.IdSetting1852, "FishingRodVo", true)
            for _, v1 in pairs(t1) do
                if checkNumber(v.id) == checkNumber(v1.screenType) then
                    table.insert(_t, v1.id)
                end
            end

            t1 = CfUtils.GetCf(AutoIds.IdSetting1846, "FishingReelVo", true)
            for _, v1 in pairs(t1) do
                if checkNumber(v.id) == checkNumber(v1.screenType) then
                    table.insert(_t, v1.id)
                end
            end
        end
    end

    if table.count(_t) > 0 then
        local strs = CfUtils.GetLocalData("FishNewGoods")
        local t = checkTable(CfUtils.Split(strs))
        for k, v in pairs(_t) do
            if checkNumber(v) > 0 then
                table.insert(t, v)
            end
        end

        strs = ""
        for k, v in pairs(t) do
            if k  > 1 then
                strs = strs..";"..v
            else
                strs = v
            end
        end
        CfUtils.WriteLocalData("FishNewGoods", strs)
    end
end

function FishingUtils.AddFishPlaceAtlasCollectNum(placeId, num)
    ---@type FishingComponent
    local fishComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.FishingComponent)
    local placeDojo = fishComp:GetFishingPlaceDojo(placeId)
    placeDojo:AddCollectNum(num)
end

return FishingUtils
